    }
    g.beginPath(); g.arc(sx, sy, Math.max(10, H * 0.03), 0, TAU); g.fillStyle = api.rgba(C.sun, 0.95); g.fill();
  }

  function buildClouds(LW, n, scale, baseY, k, alpha, haze) {
