    for (var i = 0; i <= 40; i++) {
      var f = i / 40, x = x0 + (x1 - x0) * f, y = y0 + (y1 - y0) * f + sag * 4 * f * (1 - f);
      if (prev) { g.globalAlpha = 0.9 * (1 - 0.75 * (api.calm ? api.calm(x, y, 30) : 0)); g.beginPath(); g.moveTo(prev[0], prev[1]); g.lineTo(x, y); g.stroke(); }
