      ctx.save(); ctx.beginPath(); ctx.rect(0, 0, W, line); ctx.clip();
      ctx.beginPath(); ctx.arc(sx, sy, r, 0, TAU); ctx.fillStyle = api.rgba(sun, 0.85 * e); ctx.fill(); ctx.restore();
      // horizon line grows from the centre
