    build();
  }

  mkGlow(); mkLantern();
  layout(api.width, api.height);
  init();

  return {
    resize: function (w, h) { layout(w, h); },
    zones: function () { build(); },
    frame: function (t, dt) {
      var i, L, s, x, y, a, fl, c, gs;
