      ctx.globalAlpha = 1;
      ctx.drawImage(bg, 0, 0, W, H);
      for (i = 0; i < twk.length; i++) {
        var q = twk[i], ta = (0.25 + 0.75 * (0.5 + 0.5 * Math.sin(t * q.sp + q.ph))) * 0.8 * q.k;
        ctx.fillStyle = 'rgba(240,240,255,' + ta.toFixed(3) + ')'; ctx.fillRect(q.x, q.y, 1.6, 1.6);
      }
