      }
      ctx.globalCompositeOperation = 'source-over';
      for (i = 0; i < lan.length; i++) {
        L = lan[i];
        if (L.s < 7) continue;
        a = Math.min(1, L.a * 1.1) * (1 - 0.7 * L.c);
        if (a < 0.01) continue;
        var lw = L.s * 0.75;
