      var al = (1 - age) * Math.min(1, age * 6) * (1 - api.calm(x, y, 40) * 0.8);
      if (al <= 0.02) continue;
      ctx.globalAlpha = al; ctx.beginPath(); ctx.arc(x, y, o.r * (1 - age * 0.4), 0, 6.283);
      ctx.fillStyle = FOAM; ctx.fill(); ctx.strokeStyle = api.rgba(INK, 0.45); ctx.stroke();
