  return {
    resize: layout,
    zones: layout,
    frame: function (t) {
      if (sky) ctx.drawImage(sky, 0, 0, W, H); else paintBack(ctx);
      row(horizon + 3, 2.5, 40, t * 0.04, api.mix(LIGHT, PAPER, 0.3), api.rgba(INK, 0.3), false, 0);
      row(midY, 8, 110, t * 0.06, api.mix(MID, PAPER, 0.25), api.rgba(INK, 0.55), true, 1);
