  var flakes = []; for (var i = 0; i < 40; i++) flakes.push({ x: R(), y: R(), r: 0.8 + R() * 2, v: 0.04 + R() * 0.08, ph: R() * TAU });
  function layout() { W = api.width; H = api.height; size = Math.min(44, H * 0.32); }
  layout();
