    sg.addColorStop(0, api.rgba(C.sun, 0.7)); sg.addColorStop(0.18, api.rgba(C.hor, 0.4)); sg.addColorStop(0.5, api.rgba(C.haze, 0.12)); sg.addColorStop(1, api.rgba(C.haze, 0));
