  }

  function place() {
    var f = api.free ? api.free(40) : null;
    if (f && f.w > 40 && f.h > 40) { sun.x = f.x + f.w * 0.72; sun.y = f.y + Math.min(f.h * 0.3, H * 0.22); }
    else { sun.x = W * 0.78; sun.y = H * 0.16; }
